use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_str = input.to_string();
    let cents = parse_cents(input_str);
    cents.map(|cents| cents.to_string())
}

fn parse_cents(input_str: &str) -> i64 {
    let mut cents = 0;
    let mut has_sign = false;
    let mut current_digit = 0;
    let mut is_negative = false;

    for c in input_str.chars() {
        if c == '-' {
            if has_sign {
                return None;
            }
            has_sign = true;
            is_negative = !is_negative;
        } else if c.is_digit(10) {
            current_digit = current_digit * 10 + c.to_digit(10).unwrap();
            if current_digit > 999999 {
                return None;
            }
        }
    }

    if has_sign {
        cents *= if is_negative { -1 } else { 1 };
    }

    cents
}

fn main() {
    let input = serde_json::Value::from("{\"input\":\"-12.30\",\"expected\":\"-1230\"}");
    let result = solve(input);
    println!("{:?}", result);
}
